  'src/screens/my-appointment-screen/my-appointment-screen.tsx',
  'src/screens/profile/profile-dependants/profile-dependants.styles.ts',
  'src/screens/profile/profile-dependants/profile-dependants.tsx',
  'src/screens/profile/profile-settings-screen/profile-settings-screen.tsx',
  'src/store/AppContext.tsx',
  'src/helper/selected-dependant-helper.ts',
  'src/helper/ticket-display-helper.ts',
].map((p) => path.join(root, p).replace(/\\/g, '/'));

const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: parsed.options,
  projectReferences: parsed.projectReferences,
});

function fmt(diag, sf) {
  const start = diag.start ?? 0;
  const file = diag.file || sf;
  const pos = file ? file.getLineAndCharacterOfPosition(start) : { line: -1, character: -1 };
  const rel = file ? path.relative(root, file.fileName) : '(no file)';
  return `${rel}:${pos.line + 1}:${pos.character + 1} TS${diag.code} ${ts.flattenDiagnosticMessageText(diag.messageText, ' ')}`;
}

const changedSet = new Set(changed.map((p) => path.normalize(p)));
const covered = [];
const missing = [];
const semanticHits = [];
const suggestionHits = [];
const deprecatedHits = [];

for (const abs of changed) {
  const sf = program.getSourceFile(abs) || program.getSourceFile(abs.replace(/\\/g, '/'));
  if (!sf) {
    missing.push(path.relative(root, abs));
    continue;
  }
  covered.push(path.relative(root, sf.fileName));
  const semantics = ts.getPreEmitDiagnostics(program, sf);
  for (const d of semantics) semanticHits.push(fmt(d, sf));
  const suggestions = program.getSuggestionDiagnostics(sf);
  for (const d of suggestions) {
    suggestionHits.push(fmt(d, sf));
    if (d.code === 6385 || d.code === 6387) deprecatedHits.push(fmt(d, sf));
  }
}

console.log(JSON.stringify({
  fileNamesInProgram: parsed.fileNames.length,
  covered,
  missing,
  semanticCount: semanticHits.length,
  suggestionCount: suggestionHits.length,
  deprecatedCount: deprecatedHits.length,
  semanticHits: semanticHits.slice(0, 80),
  suggestionHits: suggestionHits.filter(s => /TS6133|TS6138|TS6196|TS6385|TS6387|TS80006|deprecated/i.test(s)).slice(0, 80),
  allSuggestions: suggestionHits.slice(0, 40),
  deprecatedHits,
}, null, 2));
